import { describe, expect, it } from "vitest";
import { getAddress } from "ethers";
import { REVIEWED_V01_CONFIGURATION } from "../v01/reviewed-profile";
import { V01_CHAIN_ID, parseV01Profile, v01ProfileFingerprint } from "./v01-profile";

// The committed configuration is generated by scripts/createV01Profile.mjs from the
// recorded public deployment. That generator reimplements the fingerprint, so these
// assertions are the cross-check: if the generator drifts from the application's own
// canonical form, or a pinned source file changes without regenerating, the pin stops
// matching here rather than at runtime in front of a participant.
// Null is correct while no deployed pool was built from this code: shipping a
// profile that points at a pool from different code is the exact lie the pin
// prevents. Acceptance still requires it to be set — asserted in
// v01-public-verification.test.ts, which is the gate that decides acceptance.
describe.skipIf(REVIEWED_V01_CONFIGURATION === null)("reviewed v0.1 configuration", () => {
  it("is set from public deployment evidence", () => {
    expect(REVIEWED_V01_CONFIGURATION).not.toBeNull();
  });

  it("parses under the same rules the runtime applies", () => {
    const { profile } = REVIEWED_V01_CONFIGURATION!;
    const parsed = parseV01Profile(profile);
    expect(parsed.deployment.network.caip2).toBe(`eip155:${V01_CHAIN_ID}`);
    expect(parsed.deployment.environment).toBe("public-testnet");
    // Parsing normalizes addresses; a non-checksummed literal would differ here.
    expect(parsed.pool.address).toBe(profile.pool.address);
    expect(parsed.tokens.ambr).toBe(profile.tokens.ambr);
    expect(parsed.tokens.jade).toBe(profile.tokens.jade);
    expect(parsed.deployment.contracts.factory.address).toBe(profile.deployment.contracts.factory.address);
    expect(parsed.deployment.contracts.router.address).toBe(profile.deployment.contracts.router.address);
  });

  it("pins the fingerprint the application computes for it", () => {
    const { profile, pin } = REVIEWED_V01_CONFIGURATION!;
    expect(v01ProfileFingerprint(profile)).toBe(pin.profileFingerprint);
    expect(pin.releaseId).toBe(profile.deployment.releaseId);
    expect(pin.bundleSha256).toBe(profile.deployment.source.bundleSha256);
  });

  it("names five distinct checksummed targets", () => {
    const { profile } = REVIEWED_V01_CONFIGURATION!;
    const addresses = [
      profile.tokens.ambr,
      profile.tokens.jade,
      profile.pool.address,
      profile.deployment.contracts.factory.address,
      profile.deployment.contracts.router.address
    ];
    expect(new Set(addresses).size).toBe(5);
    for (const address of addresses) expect(getAddress(address)).toBe(address);
  });

  it("carries deployment receipts, not placeholders", () => {
    const { profile } = REVIEWED_V01_CONFIGURATION!;
    for (const contract of [profile.deployment.contracts.factory, profile.deployment.contracts.router]) {
      expect(contract.deploymentTxHash).toMatch(/^0x[0-9a-f]{64}$/);
      expect(contract.blockNumber).toBeGreaterThan(0);
      expect(contract.runtimeCodeHash).toMatch(/^0x[0-9a-f]{64}$/);
    }
    expect(profile.deployment.contracts.factory.deploymentTxHash).not.toBe(profile.deployment.contracts.router.deploymentTxHash);
  });
});
